export default function CleaveWorld() {
  const groupCounts = traces.reduce<number[]>((counts, trace) => {
    counts[trace.group] = (counts[trace.group] ?? 0) + 1;
    return counts;
  }, []);
  const seen = [0, 0, 0, 0];

  return (
    <svg
      className="cleaveWorldArt"
      viewBox="0 0 1774 887"
      preserveAspectRatio="xMidYMid meet"
      role="presentation"
      aria-hidden="true"
    >
      {traces.map((trace, i) => {
        const localIndex = seen[trace.group]++;
        const localCount = Math.max(1, (groupCounts[trace.group] ?? 1) - 1);
        const progress = localIndex / localCount;
        const groupStart = [1750, 2450, 3250, 4050][trace.group] ?? 1750;
        const delay = groupStart + Math.round(progress * 1900);
        const duration = 500 + (i % 8) * 48;

        return (
          <path
            key={i}
            className="cleaveWorldLine"
            d={trace.d}
            pathLength="1"
            style={{
              ["--cleave-delay" as string]: `${delay}ms`,
              ["--cleave-duration" as string]: `${duration}ms`,
            } as CSSProperties}
          />
        );
      })}
    </svg>
  );
}
